import{_ as a,o as l,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Fragmentation in Ceph- Why It Happens and How We Fix It - Mark Nelson, Clyso","description":"","frontmatter":{"title":"Fragmentation in Ceph- Why It Happens and How We Fix It - Mark Nelson, Clyso","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","分布式存储","碎片化","BlueStore","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Fragmentation_in_Ceph_-_Why_It_Happens_and_How_We_Fix_It_-_Mark_Nelson_Clyso.md","filePath":"posts/2025/Fragmentation_in_Ceph_-_Why_It_Happens_and_How_We_Fix_It_-_Mark_Nelson_Clyso.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Fragmentation_in_Ceph_-_Why_It_Happens_and_How_We_Fix_It_-_Mark_Nelson_Clyso.md"};function r(n,e,s,_,h,p){return l(),o("div",null,[...e[0]||(e[0]=[t('<h3 id="ceph-分布式存储中碎片化问题的分析与解决-mark-nelson-clyso" tabindex="-1">Ceph 分布式存储中碎片化问题的分析与解决 - Mark Nelson, Clyso <a class="header-anchor" href="#ceph-分布式存储中碎片化问题的分析与解决-mark-nelson-clyso" aria-label="Permalink to &quot;Ceph 分布式存储中碎片化问题的分析与解决 - Mark Nelson, Clyso&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议深入探讨了 Ceph 分布式存储系统中的碎片化问题及其对性能的影响。主讲人 Mark Nelson 详细分析了 FileStore 和 BlueStore 的设计差异，并探讨了优化策略，涉及对象数据、元数据、空闲空间和内存等多个方面。</p><h4 id="核心议题与讨论要点" tabindex="-1">核心议题与讨论要点 <a class="header-anchor" href="#核心议题与讨论要点" aria-label="Permalink to &quot;核心议题与讨论要点&quot;">​</a></h4><ol><li><p><strong>FileStore 时代的碎片化问题</strong></p><ul><li>FileStore 采用嵌套目录结构存储对象，导致元数据分散，引发性能瓶颈。</li><li>XFS 的 inode 限制和Btrfs 的写时复制（CoW）机制导致性能问题。</li></ul></li><li><p><strong>BlueStore 的改进与遗留挑战</strong></p><ul><li>RocksDB 作为 BlueStore 的核心，优化了元数据存储和写入性能。</li><li>BlueStore 的 CoW 机制和 SST 文件碎片化需要进一步优化。</li></ul></li><li><p><strong>碎片化优化实践</strong></p><ul><li>Elastic Shared Blobs 和 Defragment-on-Clone 方法用于优化 RBD 镜像克隆场景。</li><li>Deep Scrub 整合碎片整理，结合压缩和去重优化存储效率。</li></ul></li><li><p><strong>未来方向与未解问题</strong></p><ul><li>通过 BlueStore 的 Denk 框架批量分配内存，减少小对象开销。</li><li>Seastore 新设计预期改变碎片处理逻辑。</li><li>工具链完善，加强碎片检测与分析工具的开发。</li></ul></li></ol><h4 id="关键决策与行动计划" tabindex="-1">关键决策与行动计划 <a class="header-anchor" href="#关键决策与行动计划" aria-label="Permalink to &quot;关键决策与行动计划&quot;">​</a></h4><ul><li>推广 Elastic Shared Blobs 作为 RBD 镜像克隆的长期解决方案。</li><li>推进 Deep Scrub 整合优化，完善碎片整理与压缩的联合实现。</li><li>开发工具，增强 <code>ceph-osd</code> 碎片评分文档，探索基于 <code>blktrace</code> 和 <code>iowatcher</code> 的碎片可视化方案。</li></ul><h4 id="问答环节摘要" tabindex="-1">问答环节摘要 <a class="header-anchor" href="#问答环节摘要" aria-label="Permalink to &quot;问答环节摘要&quot;">​</a></h4><ul><li>推荐使用 <code>ceph-osd</code> 内置评分、<code>iowatcher</code> 及 RocksDB 调试日志进行碎片分析。</li><li>讨论了不同分配单元大小对碎片化影响，以及物理 vs 逻辑碎片的问题。</li></ul><h4 id="后续重点" tabindex="-1">后续重点 <a class="header-anchor" href="#后续重点" aria-label="Permalink to &quot;后续重点&quot;">​</a></h4><ul><li>加速 Deep Scrub 优化相关 PR 的合并。</li><li>邀请用户反馈碎片整理与压缩的实际场景需求。</li></ul><h4 id="会议结论" tabindex="-1">会议结论 <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;会议结论&quot;">​</a></h4><p>碎片化是 Ceph 性能优化的关键战场，需要结合架构改进与运行时策略持续攻坚。</p><p>[以上内容包含了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划，同时保留了计算机科学/Ceph相关领域的英文原文关键词，并按照 Markdown 格式进行了排版。]</p>',14)])])}const u=a(i,[["render",r]]);export{c as __pageData,u as default};
